// clippy 1.99 flags the field init generated by the diesel QueryableByName derive.
#![allow(clippy::redundant_field_names)]

use crate::app::AppHandle;
use diesel::prelude::*;
use diesel::sqlite::SqliteConnection;
use tempfile::TempDir;

use super::{init_pool, test_pool, DbPool};

#[derive(diesel::QueryableByName)]
struct JournalMode {
    #[diesel(sql_type = diesel::sql_types::Text)]
    journal_mode: String,
}

/// Wires a real file-backed pool into a bare app handle so the tests below drive
/// the actual commands, state injection included.
fn test_app() -> (AppHandle, TempDir) {
    let directory = tempfile::tempdir().expect("temp dir");
    let app = AppHandle::default();
    app.manage(test_pool(&directory));
    (app, directory)
}

#[test]
fn opening_a_fresh_database_applies_migrations_and_enables_wal() {
    let (app, _directory) = test_app();
    let pool = app.state::<DbPool>();
    let mut connection = pool.get().expect("connection");

    let mode = diesel::sql_query("PRAGMA journal_mode")
        .get_result::<JournalMode>(&mut connection)
        .expect("read journal mode");
    assert_eq!(mode.journal_mode, "wal");

    let groups = orm::schema::connection_groups::table
        .count()
        .get_result::<i64>(&mut connection)
        .expect("migrated schema is queryable");
    assert_eq!(groups, 0);
}

#[tokio::test]
async fn settings_upsert_by_key_instead_of_piling_up_rows() {
    let (app, _directory) = test_app();

    for value in ["first", "second"] {
        super::settings::set_setting(
            shared::Setting {
                key: "noverdbee-config".to_string(),
                value: value.to_string(),
            },
            app.state(),
        )
        .await
        .expect("save setting");
    }

    let settings = super::settings::get_all_settings(app.state())
        .await
        .expect("list settings");
    assert_eq!(settings.len(), 1);
    assert_eq!(settings[0].value, "second");

    let single = super::settings::get_setting("noverdbee-config".to_string(), app.state())
        .await
        .expect("get setting");
    assert_eq!(
        single.map(|setting| setting.value).as_deref(),
        Some("second")
    );
}

#[tokio::test]
async fn saving_connections_makes_and_drops_their_groups() {
    let (app, _directory) = test_app();
    let save = |record: shared::DbConnectionRecord, group: &str| {
        super::connections::connection_save(record, group.to_string(), app.state())
    };
    let groups = || async {
        super::groups::group_list(app.state())
            .await
            .expect("list groups")
            .into_iter()
            .map(|group| group.name)
            .collect::<Vec<_>>()
    };
    let new = |name: &str| shared::DbConnectionRecord {
        name: name.to_string(),
        driver: "postgres".to_string(),
        password: "secret".to_string(),
        ..Default::default()
    };

    let orders = save(new(" orders "), " production ").await.expect("create");
    let billing = save(new("billing"), "production").await.expect("create");
    assert_eq!(orders.name, "orders");
    assert_eq!(orders.group_id, billing.group_id, "one group per name");
    assert_eq!(groups().await, ["production"]);
    assert!(save(new("  "), "").await.is_err(), "a name is required");

    let moved = save(
        shared::DbConnectionRecord {
            name: "orders-ro".to_string(),
            read_only: true,
            ..orders.clone()
        },
        "staging",
    )
    .await
    .expect("update");
    assert_eq!(moved.id, orders.id);
    assert_eq!(groups().await, ["production", "staging"]);

    let ungrouped = save(billing.clone(), "").await.expect("ungroup");
    assert_eq!(ungrouped.group_id, None);
    assert_eq!(groups().await, ["staging"], "an empty group goes away");

    let listed = super::connections::connection_list(app.state())
        .await
        .expect("list connections");
    let names: Vec<&str> = listed.iter().map(|row| row.name.as_str()).collect();
    assert_eq!(names, ["billing", "orders-ro"], "updates must not add rows");
    assert!(listed[1].read_only);
    assert_eq!(listed[1].password, "secret");

    super::connections::connection_delete(orders.id, app.state())
        .await
        .expect("delete connection");
    assert!(groups().await.is_empty());
}

#[tokio::test]
async fn a_restored_backup_replaces_the_database_on_next_launch() {
    let directory = tempfile::tempdir().expect("temp dir");
    let database = directory.path().join("noverdbee.db");
    let backup = directory.path().join("backup.db");
    let save = |path: &std::path::Path, value: &str| {
        let pool = init_pool(path).expect("open database");
        let app = AppHandle::default();
        app.manage(pool);
        let setting = shared::Setting {
            key: "marker".to_string(),
            value: value.to_string(),
        };
        async move { super::settings::set_setting(setting, app.state()).await }
    };
    save(&backup, "backup").await.expect("save backup");
    save(&database, "current").await.expect("save current");

    let junk = directory.path().join("junk.db");
    std::fs::write(&junk, "not a database").expect("write junk");
    assert!(super::stage_restore(&junk, &database).is_err());
    assert!(super::check_backup(&foreign_database(&directory)).is_err());

    super::stage_restore(&backup, &database).expect("stage restore");
    super::apply_pending_restore(&database).expect("apply restore");

    let read = |path: std::path::PathBuf| async move {
        let app = AppHandle::default();
        app.manage(init_pool(&path).expect("open database"));
        super::settings::get_setting("marker".to_string(), app.state())
            .await
            .expect("get setting")
            .map(|setting| setting.value)
    };
    assert_eq!(read(database.clone()).await.as_deref(), Some("backup"));
    let previous = directory.path().join("noverdbee.db.before-restore");
    assert_eq!(read(previous).await.as_deref(), Some("current"));
    // Nothing is left staged, so the next launch does not restore again.
    assert!(!directory.path().join("noverdbee.db.restore").exists());
}

/// An empty SQLite database: valid, but not one of ours.
fn foreign_database(directory: &TempDir) -> std::path::PathBuf {
    use diesel::connection::SimpleConnection as _;
    let path = directory.path().join("other.db");
    SqliteConnection::establish(&path.to_string_lossy())
        .expect("create database")
        .batch_execute("CREATE TABLE t (x)")
        .expect("create table");
    path
}
